contract InvMutTest {
    C c;
    uint256 idx;
    uint256 util;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address asset, uint256 _index, uint256 _utilization) public {
        require(_utilization < type(uint256).max / 2);
        idx = _index;
        util = _utilization;
        // c's storage is fresh/uninitialized: slopes kink=0, slope0=0, slope1=0, rate=0.
        // rate() must therefore always return 0, regardless of reported utilization/index.
        uint256 r = c.rate(address(this), asset); if (__ESBMC_reverted()) return;
        assert(r == 0);
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        bytes4 sel = bytes4(data);
        if (sel == 0x8b56ac35) {
            // currentUtilizationIndex(address)
            return abi.encode(idx);
        }
        if (sel == 0x1a3d61d0) {
            // utilization(address)
            return abi.encode(util);
        }
        return "";
    }

    receive() external payable {}
}

